async def act(page):
    import asyncio

    # Defensive: close any visible dialog/alertdialog that might block interactions.
    for dlg_role in ("dialog", "alertdialog"):
        dlg_locator = page.get_by_role(dlg_role)
        try:
            dlg_count = await dlg_locator.count()
        except Exception:
            dlg_count = 0
        for i in range(dlg_count):
            dlg = dlg_locator.nth(i)
            # Try to close via a button whose name suggests closing
            btns = dlg.get_by_role("button")
            try:
                btn_count = await btns.count()
            except Exception:
                btn_count = 0
            closed = False
            for bi in range(btn_count):
                b = btns.nth(bi)
                name = ""
                try:
                    name = (await b.inner_text()).strip()
                except Exception:
                    try:
                        name = (await b.get_attribute("aria-label")) or ""
                    except Exception:
                        name = ""
                if any(tok in name.lower() for tok in ("close", "dismiss", "ok", "×", "x", "✖")):
                    try:
                        await b.click()
                        closed = True
                        await asyncio.sleep(0.25)
                        break
                    except Exception:
                        pass
            if closed:
                continue
            if btn_count > 0:
                try:
                    await btns.nth(0).click()
                    await asyncio.sleep(0.25)
                except Exception:
                    pass

    # Use the knowledge-base helper to perform the visible-site search for 'GPT'.
    # Utility: create_curated_collection_by_search is explicitly designed to find the site's search widget
    # and trigger a search starting from '/', then wait for results in role="main". It's the appropriate
    # helper for performing the site's visible search and is required to be used when applicable.
    await create_curated_collection_by_search(page, "GPT", max_results=0, resolve_links=True)

    # After helper completes results should be in role="main" as role="article"
    main = page.get_by_role("main")
    try:
        await main.wait_for(timeout=5000)
    except Exception:
        # small fallback delay
        await asyncio.sleep(0.5)

    articles = main.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count < 3:
        raise Exception(f"Expected at least 3 search results, found {article_count}")

    third_article = articles.nth(2)
    # Click the first accessible link inside the third article; fallback to clicking the article itself.
    links_in_third = third_article.get_by_role("link")
    try:
        links_count = await links_in_third.count()
    except Exception:
        links_count = 0

    if links_count > 0:
        await links_in_third.nth(0).click()
    else:
        await third_article.click()

